def parts(r):
 A,_=s.linear_eq_to_matrix(v.rows(r['question']),[v.x,v.y]);f=r['question'][':question/answer-fields'][0]
 opts=[(v.expr(a[':answer/value'].split('=')[1]),a[':answer/id']) for a in f[':answer-field/choices']]
 return A,opts,f[':answer-field/correct'][1]
def stats(pool):
 d=collections.defaultdict(list)
 for r in pool:
  A,opts,key=parts(r);t=r['generation']['template'];sign='same_sign' if A[1,0]*A[0,1]/A[0,0]>0 else 'opposite_sign'
